const ROOM_STATE={select_chart:'选曲中',selecting_chart:'选曲中',selectchart:'选曲中',waiting_for_ready:'准备中',waitforready:'准备中',playing:'演奏中',completed:'已完成'};
let roomEditId=null,roomRefreshTimer=null;
const roomStateLabel=value=>ROOM_STATE[String(value||'').replace(/[^a-z]/gi,'').toLowerCase()]||ROOM_STATE[String(value||'').toLowerCase()]||value||'—';
async function renderRooms(force){
  const body=$('#rooms'),box=$('#roomsStatus');
  if(!body||!box)return;
  if(roomRefreshTimer){clearTimeout(roomRefreshTimer);roomRefreshTimer=null}
  try{
    const data=await api('/api/admin/monitor/rooms'+(force?'?refresh=1':''));
    let managed=[],managedError='';
    if(canManageRooms())try{const result=await api('/api/admin/rooms');managed=result.rooms||[];state.managedRooms=managed}catch(error){managedError=error.message||String(error);state.managedRooms=[]}
    else state.managedRooms=[];
    const status=data.status||{},monitorRooms=data.rooms||[],notes=[],managedById=new Map(managed.map(room=>[room.roomid,room]));
    const rooms=monitorRooms.map(room=>({...room,managed:managedById.get(room.id)||null}));
    for(const room of managed)if(!rooms.some(item=>item.id===room.roomid))rooms.push({id:room.roomid,chartId:room.chart?.id??null,chartName:room.chart?.name??null,state:room.state||null,playerCount:(room.users||[]).length,maxUsers:room.capacity,locked:false,lastScore:null,instanceId:room.instanceId||null,managed:room});
    notes.push(status.enabled?(status.connected?'事件流已连接':'事件流未连接'):'未启用：需配置 PMP_BASE_URL 与 PMP_MONITOR_ENABLED');
    notes.push('快照 '+(status.snapshot==='ok'?'可用':status.snapshot==='unavailable'?'不可用':'未知'));
    notes.push('房间 '+number(rooms.length));
    if(canManageRooms())notes.push('可管理房间 '+number(managed.length));
    if(!data.unrestricted)notes.push('仅显示自己或协作实例的房间');
    if(status.lastError)notes.push(status.lastError);
    if(managedError)notes.push('管理接口不可用：'+managedError);
    box.textContent=notes.join(' · ');
    box.className='callout'+(status.lastError||managedError?' error':'');
    body.innerHTML=rooms.map(function(room){
      const managed=room.managed,chart=managed?.chart||null,chartId=chart?.id??room.chartId??null,chartName=chart?.name||room.chartName||null;
      const count=managed?(managed.users||[]).length:room.playerCount,max=managed?.capacity||room.maxUsers,players=count===null||count===undefined?'—':number(count)+(max?' / '+number(max):'');
      const kind=managed?(managed.hosted?'长期托管房':'预约白名单房'):'普通房间',mode=managed?.hosted?(managed.chart_mode==='POOL_RANDOM'?' · 谱池随机':' · 房主选谱')+(managed.allowed_user_ids?.length?' · 白名单':' · 公开加入'):'';
      const instanceId=room.instanceId||managed?.instanceId||null,host=managed?.host_id??room.hostId??null;
      const actions=managed&&canManageRooms()?'<div class="row-actions">'+(managed.hosted?'<button class="small" data-action="edit-room" data-room="'+esc(room.id)+'">设置</button>':'')+'<button class="small ghost" data-action="room-chat" data-room="'+esc(room.id)+'">公告</button><button class="small ghost danger" data-action="disband-room" data-room="'+esc(room.id)+'">解散</button></div>':'<span class="muted">—</span>';
      return '<tr><td><div class="mono">'+esc(room.id)+'</div><div class="chart-sub">'+kind+mode+'</div></td><td><div class="chart-name">'+esc(chartName||(chartId===null?'（未选谱面）':'#'+chartId))+'</div><div class="chart-sub">'+(chartId===null?'':'#'+chartId)+'</div></td><td>'+esc(roomStateLabel(managed?.state||room.state))+(room.locked?' · 锁定':'')+'</td><td>'+players+'</td><td>'+(host===null?'<span class="muted">待接管</span>':'<span class="mono">#'+host+'</span>')+'</td><td>'+(instanceId?'<span class="badge">'+esc(instanceId)+'</span>':'<span class="muted">未归属</span>')+'</td><td>'+actions+'</td></tr>'
    }).join('')||emptyRow(7,'当前没有房间','可以创建长期托管房或一次性预约白名单房。');
    $('#createHostedRoom').hidden=!canManageRooms();$('#createReservedRoom').hidden=!canManageRooms();
  }catch(error){
    box.textContent='房间列表加载失败：'+(error&&error.message?error.message:String(error));
    box.className='callout error';
  }
  if(state.view==='rooms')roomRefreshTimer=setTimeout(function(){renderRooms(false)},2500)
}
