function parseRoomIds(value,allowEmpty=false){const parts=String(value||'').split(/[\s,，;；]+/).filter(Boolean);if(!parts.length&&allowEmpty)return [];const ids=[...new Set(parts.map(Number))];if(!parts.length||parts.some(v=>!/^\d+$/.test(v))||ids.some(id=>!Number.isSafeInteger(id)||id<=0||id>2147483647))throw new Error('请填写有效的 Phira UID（正整数）');return ids}
function chartInput(required){const raw=$('#roomChartId').value.trim();if(!raw){if(required)throw new Error('预约房必须选择谱面');return null}const id=Number(raw),local=state.charts.find(chart=>chart.id===id),name=$('#roomChartName').value.trim()||local?.name||'';if(!Number.isSafeInteger(id)||id===0)throw new Error('谱面 ID 必须是非零整数');if(!name)throw new Error('请填写谱面名称');return {id,name}}
function parseRoomPool(){const rows=$('#roomChartPool').value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean),seen=new Set(),charts=[];for(const row of rows){const parts=row.split('|'),id=Number(parts.shift()?.trim()),local=state.charts.find(chart=>chart.id===id),name=parts.join('|').trim()||local?.name||'';if(!Number.isSafeInteger(id)||id===0||!name)throw new Error('谱池每行必须是“非零谱面ID | 谱面名称”');if(!seen.has(id)){seen.add(id);charts.push({id,name})}}return charts}
function syncRoomForm(){const hosted=$('#roomKind').value==='hosted',pool=hosted&&$('#roomChartMode').value==='POOL_RANDOM';$$('[data-room-hosted]').forEach(el=>el.hidden=!hosted);$('#roomPoolField').hidden=!pool;$('#roomExpiryField').hidden=hosted;$('#roomWhitelist').required=!hosted;$('#roomChartId').required=!hosted;$('#roomChartName').required=!hosted;$('#roomExpiry').required=!hosted;$('#roomFormHelp').textContent=hosted?(pool?'玩家 UID 可留空；留空表示所有玩家均可进入。谱池至少需要一张谱面。':'玩家 UID 可留空；留空表示所有玩家均可进入。填写白名单时，协议房主必须在白名单内。'):'预约房是一次性白名单房，必须填写玩家 UID；完整成员进入并准备后自动开始。'}
function openRoomForm(kind,roomId=null){if(state.busy||!canManageRooms())return;roomEditId=roomId;const room=roomId?state.managedRooms.find(item=>item.roomid===roomId):null;if(roomId&&!room?.hosted)return;$('#roomKind').value=kind;$('#roomTitle').textContent=room?'托管房设置 · '+room.roomid:kind==='hosted'?'创建托管房':'创建预约白名单房';$('#roomId').value=room?.roomid||'';$('#roomId').disabled=Boolean(room);$('#roomCapacity').value=room?.capacity||4;$('#roomWhitelist').value=(room?.allowed_user_ids||[]).join(', ');$('#roomHostId').value=room?.host_id||'';$('#roomChartMode').value=room?.chart_mode||'HOST_SELECT';$('#roomChartId').value=room?.chart?.id??'';$('#roomChartName').value=room?.chart?.name||'';$('#roomChartPool').value=(room?.chart_pool||[]).map(chart=>chart.id+' | '+chart.name).join('\n');$('#roomExpiry').value=1800;syncRoomForm();$('#roomDialog').showModal()}
$('#createHostedRoom').onclick=()=>openRoomForm('hosted');$('#createReservedRoom').onclick=()=>openRoomForm('reserved');$('#roomChartMode').onchange=syncRoomForm;$('#roomChartId').oninput=()=>{const chart=state.charts.find(item=>item.id===Number($('#roomChartId').value));if(chart)$('#roomChartName').value=chart.name};
$('#roomForm').onsubmit=e=>{e.preventDefault();const hosted=$('#roomKind').value==='hosted';let ids,chart,pool;try{ids=parseRoomIds($('#roomWhitelist').value,hosted);chart=chartInput(!hosted);pool=parseRoomPool()}catch(error){toast(error.message,true);return}const hostRaw=$('#roomHostId').value.trim(),hostId=hostRaw?Number(hostRaw):null;if(hosted&&ids.length&&hostId!==null&&!ids.includes(hostId)){toast('填写白名单时，协议房主必须在白名单内',true);return}const data=hosted?{roomId:$('#roomId').value.trim(),allowedUserIds:ids,maxUsers:Number($('#roomCapacity').value),hostId,chart,chartMode:$('#roomChartMode').value,chartPool:pool}:{roomId:$('#roomId').value.trim(),allowedUserIds:ids,chart,expiresInSeconds:Number($('#roomExpiry').value)};task(e.submitter,async()=>{const path=roomEditId?'/api/admin/rooms/'+encodeURIComponent(roomEditId)+'/hosted':hosted?'/api/admin/rooms/hosted':'/api/admin/rooms/precreate';if(roomEditId)delete data.roomId;const result=await api(path,jsonOptions(roomEditId?'PATCH':'POST',data));$('#roomDialog').close();toast(result.created===false?'相同配置的房间已经存在':roomEditId?'房间设置已保存':'房间已创建');await renderRooms(true)})};
$('#rooms').onclick=e=>{const button=e.target.closest('[data-action]');if(!button||state.busy)return;const roomId=button.dataset.room;if(button.dataset.action==='edit-room')openRoomForm('hosted',roomId);if(button.dataset.action==='room-chat'){$('#roomChatId').value=roomId;$('#roomChatMessage').value='';$('#roomChatTitle').textContent='发送房间公告 · '+roomId;$('#roomChatDialog').showModal()}if(button.dataset.action==='disband-room')task(button,async()=>{await api('/api/admin/rooms/'+encodeURIComponent(roomId)+'/disband',jsonOptions('POST',{}));toast('房间已解散');await renderRooms(true)})};
$('#roomChatForm').onsubmit=e=>{e.preventDefault();const roomId=$('#roomChatId').value,message=$('#roomChatMessage').value.trim();task(e.submitter,async()=>{await api('/api/admin/rooms/'+encodeURIComponent(roomId)+'/chat',jsonOptions('POST',{message}));$('#roomChatDialog').close();toast('公告已发送')})};
function openEdit(id){if(state.busy)return;const c=state.charts.find(c=>c.id===id);if(!c)return;editId=id;$('#editTitle').textContent='编辑谱面 #'+id;const form=$('#editForm');for(const key of ['name','level','difficulty','charter','composer','illustrator','description'])form.elements[key].value=c[key]??'';form.elements.tags.value=(c.tags||[]).join(', ');form.elements.listed.checked=c.listed!==false;$('#editDialog').showModal()}
function openInstance(id=null){if(state.busy)return;const i=state.instances.find(i=>i.id===id);instanceEditId=id;$('#instanceTitle').textContent=i?'实例设置 · '+i.name:'创建服务实例';$('#instanceId').value=i?.id||'';$('#instanceId').disabled=Boolean(i);$('#instanceName').value=i?.name||'';$('#instanceHosts').value=(i?.hosts||[]).join(', ');$('#instanceEnabled').checked=i?i.enabled:true;$('#instanceHosts').closest('label').hidden=state.user?.role!=='admin';$('#instanceVisibility option[value=legacy]').hidden=Boolean(!i||i.visibility);$('#instanceVisibility').value=i?(i.visibility?.mode||'legacy'):'none';$('#instanceViewers').value=(i?.visibility?.userIds||[]).join('\n');$('#instanceListingWarning').hidden=(i?.listingEnabled??state.instances[0]?.listingEnabled)!==false;syncAudience();prepareInstancePolicy(id);$('#instanceDialog').showModal()}
function confirmDelete(title,message,action){if(state.busy)return;$('#confirmTitle').textContent=title;$('#confirmText').textContent=message;$('#confirmInput').value='';$('#confirmAction').disabled=true;confirmCallback=action;$('#confirmDialog').showModal()}
function deleteCharts(ids){if(!ids.length){toast('没有可删除的谱面',true);return}const scopedIds=[...ids],instance=state.instance;const records=state.records.filter(r=>scopedIds.includes(r.chart)).length;const preview=state.charts.filter(c=>scopedIds.includes(c.id)).slice(0,4).map(c=>c.name+' (#'+c.id+')').join('、');confirmDelete('删除 '+scopedIds.length+' 张谱面','实例：「'+currentName()+'」\n将删除 '+scopedIds.length+' 张谱面、对应资源和 '+records+' 条成绩。\n'+preview+(scopedIds.length>4?' 等':'')+'\n此操作不可撤销。',async()=>{if(instance!==state.instance)throw new Error('实例已切换，请重新选择');const result=scopedIds.length===1?await api('/api/admin/charts/'+scopedIds[0],{method:'DELETE'}):await api('/api/admin/charts/batch-delete',jsonOptions('POST',{ids:scopedIds}));if(!result.deletedIds)result.deletedIds=[result.id];$('#confirmDialog').close();state.selected.clear();toast('已删除 '+result.deletedIds.length+' 张谱面、'+result.recordsDeleted+' 条成绩');await refresh()})}
async function downloadChart(id){const response=await fetch('/api/admin/download/'+id+'?instance='+encodeURIComponent(state.instance),{credentials:'same-origin',headers:$('#token').value?{Authorization:'Bearer '+$('#token').value.trim()}:{}});if(!response.ok)throw new Error('下载失败（HTTP '+response.status+'）');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='#'+id+'_'+chartName(id).replace(/[<>:"/\\|?*]/g,'_')+'.pez';link.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
$('#navToggle').onclick=()=>{const open=!$('#workspace').classList.contains('nav-open');$('#workspace').classList.toggle('nav-open',open);$('#sidebarScrim').hidden=!open;$('#navToggle').setAttribute('aria-expanded',String(open));if(open)$('#sidebarClose').focus()};$('#sidebarClose').onclick=()=>{closeNavigation();$('#navToggle').focus()};$('#sidebarScrim').onclick=closeNavigation;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#workspace').classList.contains('nav-open')){closeNavigation();$('#navToggle').focus()}});$$('[data-view]').forEach(b=>b.onclick=()=>{if(b.dataset.view==='docs'){$('#docDialog').showModal();closeNavigation()}else showView(b.dataset.view)});$$('[data-go]').forEach(b=>b.onclick=()=>showView(b.dataset.go));$$('[data-close]').forEach(b=>b.onclick=()=>{if(!state.busy)$('#'+b.dataset.close).close()});$$('dialog').forEach(d=>d.addEventListener('cancel',e=>{if(state.busy)e.preventDefault()}));$('#connectionButton').onclick=()=>{showView('settings');$('#token').focus()};$('#reload').onclick=e=>task(e.currentTarget,refresh);$('#instanceSelect').onchange=e=>task(null,()=>switchInstance(e.target.value));
