$('#charts').onchange=e=>{if(!e.target.matches('.chart-check'))return;const id=Number(e.target.value);e.target.checked?state.selected.add(id):state.selected.delete(id);renderCharts()};$('#chartHeaderCheck').onchange=e=>{const page=filteredCharts().slice((state.chartPage-1)*20,state.chartPage*20);page.forEach(c=>e.target.checked?state.selected.add(c.id):state.selected.delete(c.id));renderCharts()};$('#selectFiltered').onclick=()=>{filteredCharts().forEach(c=>state.selected.add(c.id));renderCharts()};$('#clearSelection').onclick=()=>{state.selected.clear();renderCharts()};$('#deleteSelected').onclick=()=>deleteCharts([...state.selected]);$('#deleteByTag').onclick=()=>{const tag=$('#deleteTag').value;if(!tag){toast('请先选择标签',true);return}deleteCharts(state.charts.filter(c=>(c.tags||[]).includes(tag)).map(c=>c.id))};$('#deleteAll').onclick=()=>deleteCharts(state.charts.map(c=>c.id));
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||state.busy)return;const id=Number(b.dataset.id),action=b.dataset.action;if(action==='edit')openEdit(id);if(action==='delete')deleteCharts([id]);if(action==='visibility')task(b,async()=>{const c=state.charts.find(c=>c.id===id);await api('/api/admin/charts/'+id,jsonOptions('PATCH',{listed:c.listed===false}));toast(c.listed===false?'谱面已设为在线显示':'谱面已隐藏');await refresh()});if(action==='download')task(b,()=>downloadChart(id));if(action==='preview')openPreview(id);if(action==='delete-record')confirmDelete('删除成绩 #'+id,'实例：「'+currentName()+'」\n此成绩将永久删除，无法撤销。',async()=>{await api('/api/admin/records/'+id,{method:'DELETE'});$('#confirmDialog').close();toast('成绩已删除');await refresh()});if(action==='switch-instance')task(b,()=>switchInstance(b.dataset.instance));if(action==='edit-instance')openInstance(b.dataset.instance);if(action==='delete-instance'){const i=state.instances.find(i=>i.id===b.dataset.instance);confirmDelete('删除实例「'+i.name+'」','将永久删除该实例及其 '+i.chartCount+' 张谱面、'+i.recordCount+' 条成绩和资源。',async()=>{await api('/api/admin/instances/'+encodeURIComponent(i.id),{method:'DELETE'});$('#confirmDialog').close();if(state.instance===i.id){state.instance='default';resetFilters()}toast('实例已删除');await refresh()})}});
