$('#editForm').onsubmit=e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));data.difficulty=Number(data.difficulty);data.tags=tags(data.tags);data.listed=form.elements.listed.checked;if(!capability('chart.tags'))delete data.tags;if(!capability(data.listed?'chart.publish':'chart.hide'))delete data.listed;task(e.submitter,async()=>{await api('/api/admin/charts/'+editId,jsonOptions('PATCH',data));$('#editDialog').close();toast('谱面信息已保存');await refresh()})};
$('#batchTags').onclick=()=>{if(state.busy)return;$('#tagsScope').textContent='将修改「'+currentName()+'」中选中的 '+state.selected.size+' 张谱面。';$('#tagsDialog').showModal()};$('#tagsForm').onsubmit=e=>{e.preventDefault();const mode=$('#tagMode').value,values=tags($('#changeTags').value);if(mode!=='replace'&&!values.length){toast('请输入至少一个标签',true);return}const ids=[...state.selected];task(e.submitter,async()=>{const result=await api('/api/admin/charts/batch-tags',jsonOptions('POST',{ids,tags:values,mode}));$('#tagsDialog').close();toast('已更新 '+result.updated.length+' 张谱面的标签');await refresh()})};
$('#addRecord').onclick=()=>{if(!state.charts.length){toast('请先上传谱面',true);return}$('#recordDialog').showModal()};$('#recordForm').onsubmit=e=>{e.preventDefault();const form=e.target,f=new FormData(form),data={};for(const key of ['player','chart','score','accuracy','perfect','good','bad','miss','maxCombo'])data[key]=Number(f.get(key)||0);data.accuracy/=100;data.fullCombo=form.elements.fullCombo.checked;task(e.submitter,async()=>{await api('/api/admin/records',jsonOptions('POST',data));$('#recordDialog').close();form.reset();toast('本地成绩已保存');await refresh()})};
$('#createInstance').onclick=()=>openInstance();$('#instanceForm').onsubmit=e=>{e.preventDefault();const data={name:$('#instanceName').value.trim(),hosts:tags($('#instanceHosts').value),enabled:$('#instanceEnabled').checked};const mode=$('#instanceVisibility').value;if(mode!=='legacy'){const raw=$('#instanceViewers').value.trim();const parts=raw?raw.split(/[\s,，;；]+/).filter(Boolean):[];const userIds=[...new Set(parts.map(Number))];if(mode==='users'&&(!parts.length||parts.some(v=>!/^\d+$/.test(v))||userIds.length>1000||userIds.some(id=>!Number.isSafeInteger(id)||id<=0||id>2147483647))){toast('请填写 1–1000 个有效的 Phira UID（正整数）',true);return}data.visibility={mode,userIds:mode==='users'?userIds:[]}}if(state.user?.role!=='admin')delete data.hosts;if(instanceEditId){if($('#instanceName').disabled)delete data.name;if($('#instanceVisibility').disabled)delete data.visibility;if($('#instanceEnabled').disabled)delete data.enabled}if(!instanceEditId)data.id=$('#instanceId').value.trim();task(e.submitter,async()=>{const result=await api('/api/admin/instances'+(instanceEditId?'/'+encodeURIComponent(instanceEditId):''),jsonOptions(instanceEditId?'PATCH':'POST',data));$('#instanceDialog').close();if(!instanceEditId){state.instance=result.id;resetFilters()}toast(instanceEditId?'实例设置已保存':'实例已创建');await refresh()})};
function fileChanged(){const file=$('#packageInput').files[0];$('#fileName').textContent=file?file.name+' · '+(file.size/1024/1024).toFixed(2)+' MB':'';$('#packageInput').setCustomValidity(file&&!/\.(pez|zip)$/i.test(file.name)?'请选择 .pez 或 .zip 谱面包':'')}
$('#packageInput').onchange=fileChanged;$('#dropzone').addEventListener('dragover',e=>{e.preventDefault();if(!state.busy)e.currentTarget.classList.add('dragover')});$('#dropzone').addEventListener('dragleave',e=>e.currentTarget.classList.remove('dragover'));$('#dropzone').addEventListener('drop',e=>{e.preventDefault();e.currentTarget.classList.remove('dragover');if(state.busy)return;if(e.dataTransfer.files.length!==1){toast('每次请选择一个谱面包或合集 ZIP',true);return}$('#packageInput').files=e.dataTransfer.files;fileChanged()});
$('#chartForm').onsubmit=e=>{e.preventDefault();const form=e.target,f=new FormData(form);for(const [key,value] of [...f.entries()])if(typeof value==='string'&&!value.trim())f.delete(key);task(e.submitter,async()=>{$('#uploadProgress').hidden=false;$('#uploadStatus').textContent='上传并解析中，请稍候…';$('#uploadResult').hidden=true;const controls=Array.from(form.elements);controls.forEach(el=>el.disabled=true);try{const result=await api('/api/admin/charts',{method:'POST',body:f});form.reset();fileChanged();const box=$('#uploadResult');box.className='callout';box.replaceChildren();const summary=document.createElement('strong');summary.textContent=result.collection?'合集导入完成：新增 '+result.created.length+' 张，跳过 '+result.skipped.length+' 个文件':'「'+result.name+'」上传成功';box.append(summary);if(result.collection&&result.skipped.length){const ul=document.createElement('ul');result.skipped.forEach(item=>{const li=document.createElement('li');li.textContent=typeof item==='string'?item:(item.file||item.filename||item.name||'文件')+'：'+(item.reason||item.error||'已跳过');ul.append(li)});box.append(ul)}box.hidden=false;toast(summary.textContent)}catch(error){$('#uploadResult').textContent='上传未完成：'+error.message;$('#uploadResult').className='callout error';$('#uploadResult').hidden=false;throw error}finally{controls.forEach(el=>el.disabled=false);$('#uploadProgress').hidden=true;$('#uploadStatus').textContent=''}await refresh()})};
$('#connectForm').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await refresh();const token=$('#token').value.trim();storage.set('localStorage',TOKEN_KEY,$('#rememberToken').checked?token:'');storage.set('sessionStorage',TOKEN_KEY,$('#rememberToken').checked?'':token);toast('已连接到「'+currentName()+'」');showView('charts')})};$('#forgetToken').onclick=()=>{if(state.busy)return;storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');$('#token').value='';$('#rememberToken').checked=false;state.instances=[];state.charts=[];state.records=[];state.selected.clear();$('#loadError').hidden=true;$('#lastUpdated').textContent='等待连接';setConnected(false);render();toast('已清除当前浏览器的连接凭据')};

function renderAccount(){if(!canReview()){$('#reviewDialog').close();$('#reviewApplication').replaceChildren();$('#reviewHistory').replaceChildren();$('#reviewForm').reset();reviewUserId=null}const user=state.user,admin=user?.role==='admin',pending=awaitingApproval(),staff=canReview()||canManageInstances();$('#usersNav').hidden=!canUsers();$('#applicationNav').hidden=!user||admin;$$('[data-view]').forEach(b=>{if(['users','application'].includes(b.dataset.view))return;const denied=b.dataset.view==='rooms'&&!capability('monitor.view')||b.dataset.view==='audit'&&!capability('audit.read');b.hidden=denied||Boolean(pending)&&!['settings','docs'].includes(b.dataset.view)});$('#accountName').textContent=user?(user.username+' · '+levelName(user)):'';$('#accountQuota').textContent=user?(pending?statusLabel(user.approvalStatus):admin?'可管理全部用户与实例':('自己的实例 '+state.instances.filter(i=>i.ownerId===user.id).length+' / '+user.instanceLimit)):'';$('#accountDetails').textContent=user?'当前账号：'+user.username+'。密码修改后，需要重新登录。':'';$('#passwordForm').hidden=user?.id===0;$('#uploadInstance').textContent=state.instances.length?currentName():'请先创建实例'}

