function clearSession(){reviewUserId=null;permissionsUserId=null;$$('dialog').forEach(d=>d.close());for(const id of ['editForm','recordForm','chartForm','instanceForm','applicationForm','reviewForm','permissionsForm'])$('#'+id).reset();fileChanged();resetFilters();state.user=null;clearPolicyCache();state.csrf='';state.instances=[];state.charts=[];state.records=[];state.users=[];state.selected.clear();$('#token').value='';storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');setConnected(false);$('#workspace').hidden=true;$('#authGate').hidden=false;$('#passwordForm').reset();render()}
async function enterSession(session){state.user=session.user;state.csrf=session.csrf;$('#token').value='';storage.set('localStorage',TOKEN_KEY,'');storage.set('sessionStorage',TOKEN_KEY,'');$('#authGate').hidden=true;$('#workspace').hidden=false;await refresh();const view=awaitingApproval()?'application':state.instances.length?'charts':'instances';showView(titles[initialView]?initialView:view);if(initialView==='docs')$('#docDialog').showModal()}
for(const [id,action] of [['loginForm','login'],['registerForm','register'],['setupForm','setup']])$('#'+id).onsubmit=e=>{e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));if(data.confirmPassword!==undefined&&data.password!==data.confirmPassword){$('#authError').textContent='两次输入的密码不一致';$('#authError').hidden=false;return}delete data.confirmPassword;if(action==='register'){data.application=readApplication(form);for(const key of ['reason','useType','organization','socialAccount','notes'])delete data[key]}task(e.submitter,async()=>{try{$('#authError').hidden=true;const session=await api('/api/admin/auth/'+action,jsonOptions('POST',data));form.reset();await enterSession(session);toast(action==='login'?'已登录':action==='setup'?'超级管理员已创建':'注册申请已提交，请等待审核')}catch(error){$('#authError').textContent=error.message;$('#authError').hidden=false;throw error}})};
$('#logoutButton').onclick=e=>task(e.currentTarget,async()=>{await api('/api/admin/auth/logout',jsonOptions('POST',{}));clearSession();toast('已退出登录')});
$('#passwordForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.password!==data.confirmPassword){toast('两次输入的新密码不一致',true);return}delete data.confirmPassword;task(e.submitter,async()=>{await api('/api/admin/auth/password',jsonOptions('POST',data));clearSession();toast('密码已修改，请重新登录')})};

function readApplication(form){const data=new FormData(form);return Object.fromEntries(['reason','useType','organization','socialAccount','notes'].map(key=>[key,String(data.get(key)||'')]))}
function groupField(form){const group=form.elements.useType.value==='group';form.querySelector('[data-organization]').hidden=!group;form.elements.organization.required=group}
for(const id of ['registerForm','applicationForm'])$('#'+id).elements.useType.onchange=()=>groupField($('#'+id));
function renderApplication(){const user=state.user;if(!user)return;const form=$('#applicationForm');for(const key of ['reason','useType','organization','socialAccount','notes'])form.elements[key].value=user.application?.[key]|| (key==='useType'?'personal':'');groupField(form);const approved=user.approvalStatus==='approved';Array.from(form.elements).forEach(el=>el.disabled=approved);$('#resubmitApplication').hidden=approved;$('#applicationStatus').className='callout'+(user.approvalStatus==='rejected'?' error':'');$('#applicationStatus').textContent=approved?'申请已通过，可以使用实例管理功能。':user.approvalStatus==='rejected'?'申请未通过。审核意见：'+(user.reviewNote||'请补充资料后重新提交。'):'申请正在等待审核，通过前不能创建或管理实例。你可以补充下方资料并重新提交。';$('#applicationReviewedAt').textContent=user.reviewedAt?'审核于 '+formatTime(user.reviewedAt):''}
$('#applicationForm').onsubmit=e=>{e.preventDefault();const application=readApplication(e.target);task(e.submitter,async()=>{const result=await api('/api/admin/auth/application',jsonOptions('POST',{application}));state.user=result.user;toast('申请资料已更新，等待审核');await refresh()})};
async function openReview(id){const user=state.users.find(u=>u.id===id);if(!user)return;reviewUserId=id;reviewRevision=user.applicationRevision;$('#reviewTitle').textContent='注册申请 · '+user.username;const a=user.application||{},items=[['审核状态',statusLabel(user.approvalStatus)],['注册原因',a.reason||'升级前账号，未填写申请资料'],['用途类型',a.useType==='group'?'团体用途':'个人用途'],['团体名称',a.organization||'—'],['社交账号',a.socialAccount||'—'],['补充说明',a.notes||'—'],['上次审核意见',user.reviewNote||'—']];$('#reviewApplication').innerHTML='<dl>'+items.map(([key,value])=>'<dt>'+esc(key)+'</dt><dd>'+esc(value)+'</dd>').join('')+'</dl>';$('#reviewForm').hidden=user.approvalStatus!=='pending'||user.disabled||user.id===state.user.id;for(const option of $('#reviewDecision').options)option.disabled=!state.user.globalCapabilities.includes(option.value==='rejected'?'review.reject':'review.approve');$('#reviewNote').value='';$('#reviewDecision').value='approved';$('#reviewNote').required=false;const history=await api('/api/admin/users/'+id+'/history');$('#reviewHistory').innerHTML=history.map(item=>'<p>'+esc(formatTime(item.created))+' · '+esc({approved:'审核通过',rejected:'审核拒绝',resubmit:'重新提交',permissions:'权限调整'}[item.action]||item.action)+' · 操作者 #'+item.actorId+'<br>'+esc(item.note)+'</p>').join('')||'暂无处理记录';$('#reviewDialog').showModal()}
$('#reviewDecision').onchange=()=>$('#reviewNote').required=$('#reviewDecision').value==='rejected';
$('#reviewForm').onsubmit=e=>{e.preventDefault();task(e.submitter,async()=>{await api('/api/admin/users/'+reviewUserId+'/review',jsonOptions('POST',{revision:reviewRevision,decision:$('#reviewDecision').value,note:$('#reviewNote').value.trim()}));$('#reviewDialog').close();toast('审核结果已保存');await refresh()})};


