var DOC_META={user:{title:'用户接入指南',intro:'Phira 客户端连接与使用说明。'},api:{title:'API 文档',intro:'接口、接入方式与错误码。'}};
var docPdfId='';
var DOC_BT=String.fromCharCode(96),DOC_FENCE=DOC_BT+DOC_BT+DOC_BT;
function docInline(value){var text=esc(value);text=text.replace(new RegExp(DOC_BT+'([^'+DOC_BT+']+)'+DOC_BT,'g'),'<code>$1</code>');text=text.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');text=text.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g,function(whole,label,url){return '<a href="'+url+'"'+(/^https?:\/\//i.test(url)?' target="_blank" rel="noopener"':'')+'>'+label+'</a>'});return text}
function docRow(line){return line.replace(/^\s*\|/,'').replace(/\|\s*$/,'').split('|').map(cell=>docInline(cell.trim()))}
function renderMarkdown(source){source=String(source||'').replace(/\r\n?/g,'\n');var lines=source.split('\n'),out=[],i=0;while(i<lines.length){var trim=lines[i].trim();if(!trim){i++;continue}if(trim.indexOf(DOC_FENCE)===0){var code=[];i++;while(i<lines.length&&lines[i].trim().indexOf(DOC_FENCE)!==0){code.push(lines[i]);i++}i++;out.push('<pre><code>'+esc(code.join('\n'))+'</code></pre>');continue}if(i+1<lines.length&&lines[i].indexOf('|')>=0&&/^\s*\|?[\s:|-]+\|?\s*$/.test(lines[i+1])&&lines[i+1].indexOf('-')>=0){var rows=[docRow(lines[i])];i+=2;while(i<lines.length&&lines[i].trim().indexOf('|')>=0){rows.push(docRow(lines[i]));i++}var head=rows.shift()||[];out.push('<div class="doc-table-scroll"><table><thead><tr>'+head.map(cell=>'<th>'+cell+'</th>').join('')+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue}var heading=/^(#{1,6})\s+(.*)$/.exec(trim);if(heading){var level=heading[1].length;out.push('<h'+level+'>'+docInline(heading[2])+'</h'+level+'>');i++;continue}if(/^\s*([-*_])\s*\1\s*\1(?:\s*\1)*\s*$/.test(trim)){out.push('<hr>');i++;continue}if(trim.indexOf('>')===0){var quote=[];while(i<lines.length&&(lines[i].trim().indexOf('>')===0||!lines[i].trim())){if(lines[i].trim().indexOf('>')===0)quote.push(lines[i].replace(/^\s*>\s?/,''));else quote.push('');i++}out.push('<blockquote>'+renderMarkdown(quote.join('\n'))+'</blockquote>');continue}var bullet=/^\s*([-*+])\s+(.*)$/.exec(trim),number=/^\s*\d+\.\s+(.*)$/.exec(trim);if(bullet||number){var ordered=Boolean(number);out.push(ordered?'<ol>':'<ul>');while(i<lines.length){var item=bullet=/^\s*([-*+])\s+(.*)$/.exec(lines[i].trim()),itemNum=/^\s*\d+\.\s+(.*)$/.exec(lines[i].trim());if(!(bullet||itemNum))break;var content=(bullet?bullet[2]:itemNum[1]);i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,6})\s|^\s*[-*+]\s|^\s*\d+\.\s|^\s*>\s?/.test(lines[i])&&lines[i].indexOf('|')<0&&lines[i].trim().indexOf(DOC_FENCE)!==0){content+=' '+lines[i].trim();i++}out.push('<li>'+docInline(content)+'</li>')}out.push(ordered?'</ol>':'</ul>');continue}var paragraph=[];while(i<lines.length&&lines[i].trim()&&!/^(#{1,6})\s|^\s*[-*+]\s|^\s*\d+\.\s|^\s*>\s?/.test(lines[i])&&lines[i].trim().indexOf(DOC_FENCE)!==0&&!(lines[i].indexOf('|')>=0&&i+1<lines.length&&/^\s*\|?[\s:|-]+\|?\s*$/.test(lines[i+1])&&lines[i+1].indexOf('-')>=0)){paragraph.push(lines[i]);i++}out.push('<p>'+paragraph.map(line=>docInline(line)).join('<br>')+'</p>')}return out.join('\n')}
var docReturnView='charts';
function openDocument(id){if(!DOC_META[id])return;docPdfId=id;var dialog=$('#docDialog');if(dialog&&dialog.open)dialog.close();docReturnView=state.view==='docs'?'charts':state.view;var meta=DOC_META[id];$('#docHeading').textContent=meta.title;$('#docIntro').textContent=meta.intro;var status=$('#docStatus'),loading=$('#docLoading'),content=$('#docContent');status.hidden=true;status.className='callout';loading.hidden=false;content.hidden=true;content.innerHTML='';task(null,async()=>{try{var doc=await api('/api/admin/docs/'+id);content.innerHTML=renderMarkdown(doc.content||'');loading.hidden=true;content.hidden=false}catch(error){loading.hidden=true;content.hidden=true;status.textContent=error.message||'文档加载失败';status.className='callout error';status.hidden=false}finally{showView('docs')}})}
$('#docBack').onclick=()=>showView(docReturnView==='docs'?'charts':docReturnView);
async function printDocument(){if(!DOC_META[docPdfId])return;var response=await fetch(scopedPath('/api/admin/docs/'+docPdfId+'/print'),{credentials:'same-origin',cache:'no-store',headers:$('#token').value.trim()?{Authorization:'Bearer '+$('#token').value.trim()}:{}});if(!response.ok){var message='打印视图加载失败（HTTP '+response.status+'）';try{var detail=await response.json();if(detail&&detail.error)message=detail.error}catch(error){}throw new Error(message)}var source=await response.text(),frame=document.createElement('iframe');frame.setAttribute('aria-hidden','true');frame.style.cssText='position:fixed;left:-10000px;top:0;width:1024px;height:1414px;border:0';frame.addEventListener('load',function(){var view=frame.contentWindow;if(!view){frame.remove();toast('无法打开打印视图',true);return}var cleanup=function(){frame.remove()};view.addEventListener('afterprint',cleanup,{once:true});setTimeout(cleanup,60000);view.focus();setTimeout(function(){view.print()},50)},{once:true});document.body.append(frame);frame.srcdoc=source}
$('#docPrint').onclick=e=>task(e.currentTarget,printDocument);
$$('.doc-option').forEach(option=>option.onclick=()=>openDocument(option.dataset.doc));
(function(){var connection=$('#connectionButton');if(!connection)return;var button=document.createElement('button');button.className='ghost';button.id='docButton';button.type='button';button.title='打开使用文档';button.textContent='使用文档';connection.parentNode.insertBefore(button,connection);button.onclick=()=>{if(!state.busy)$('#docDialog').showModal()}})();
